#!/usr/bin/env python3
"""Freeze a tiny independent Transformers/PIL Qwen3.5 vision fixture."""
import hashlib,json,sys
import numpy as np
import torch,transformers
from PIL import Image
from transformers.models.qwen3_5.configuration_qwen3_5 import Qwen3_5VisionConfig
from transformers.models.qwen3_5.modeling_qwen3_5 import Qwen3_5VisionModel
from transformers.models.qwen2_vl.image_processing_pil_qwen2_vl import Qwen2VLImageProcessorPil

torch.set_num_threads(1)
c=Qwen3_5VisionConfig(depth=2,hidden_size=16,intermediate_size=24,num_heads=2,out_hidden_size=8,patch_size=2,temporal_patch_size=2,spatial_merge_size=2,num_position_embeddings=16,deepstack_visual_indexes=[])
c._attn_implementation='eager';m=Qwen3_5VisionModel(c).float().eval();params=[]
with torch.no_grad():
 for k,(name,p) in enumerate(m.named_parameters()):
  plus=name.endswith('.weight') and 'norm' in name
  values=((torch.arange(p.numel())*7+k*3)%23-11).float()/64+(1 if plus else 0)
  p.copy_(values.reshape(p.shape));shape=list(p.shape)
  if len(shape)==5:shape=[shape[0],int(np.prod(shape[1:]))]
  params.append((name,k,plus,shape))
rgb=np.array([(i*7+3)%256 for i in range(7*11*3)],dtype=np.uint8).reshape(7,11,3)
proc=Qwen2VLImageProcessorPil(patch_size=2,temporal_patch_size=2,merge_size=2,image_mean=[.5]*3,image_std=[.5]*3,size={'shortest_edge':16,'longest_edge':256})
px=proc(images=Image.fromarray(rgb),return_tensors='pt')
with torch.no_grad():features=m(px['pixel_values'],grid_thw=px['image_grid_thw']).pooler_output.numpy()
meta={'source_layout_version':1,'channels':3,'embedding_length':16,'output_length':8,'block_count':2,'attention.head_count':2,'feed_forward_length':24,'patch_size':2,'temporal_patch_size':2,'merge_size':2,'position_count':16,'min_pixels':16,'max_pixels':256,'text_rope_dim':8,'image_token_id':100,'vision_start_token_id':101,'vision_end_token_id':102,'mrope_section.0':2,'mrope_section.1':1,'mrope_section.2':1}
L=[f'/* Independent Transformers {transformers.__version__} F32/eager + PIL reference. Generated by qwen35_vision_fixture_gen.py. */', 'static int vision_fixture(const char *path,int malformed) {','gguf_writer *w=gguf_write_open(path);if(!w)return 1;','gguf_write_kv_str(w,"general.architecture","qwen35_vision");']
for k,v in meta.items():L.append(f'gguf_write_kv_u32(w,"qwen35_vision.{k}",{v});')
L+=['gguf_write_kv_f32(w,"qwen35_vision.rope.freq_base",10000.0f);','struct tensor { const char *name; int index,plus,rank; uint64_t shape[2]; } ts[]={']
for name,k,plus,shape in params:
 s=list(reversed(shape))+[1]*(2-len(shape));L.append('{"%s",%d,%d,%d,{%d,%d}},'%(name,k,plus,len(shape),*s))
L+=['};','for(size_t t=0;t<sizeof(ts)/sizeof(ts[0]);t++)if(!malformed || strcmp(ts[t].name,"blocks.1.norm2.bias"))gguf_write_tensor_decl(w,ts[t].name,ts[t].rank,ts[t].shape,GGUF_TYPE_F32);','for(size_t t=0;t<sizeof(ts)/sizeof(ts[0]);t++){struct tensor *a=&ts[t];','if(malformed && !strcmp(a->name,"blocks.1.norm2.bias"))continue;','size_t n=a->shape[0]*a->shape[1];float *x=malloc(n*sizeof(float));if(!x){gguf_write_abort(w);return 1;}','for(size_t j=0;j<n;j++)x[j]=(float)((int)((j*7+a->index*3)%23)-11)/64.0f+a->plus;','int rc=gguf_write_tensor_f32(w,a->name,x,n);free(x);if(rc){gguf_write_abort(w);return 1;}','}return gguf_write_close(w);}','static const float vision_golden[]={'+','.join(float(x).hex()+'f' for x in features.ravel())+'};','static const char vision_patches_sha[]="'+hashlib.sha256(px['pixel_values'].numpy().tobytes()).hexdigest()+'";']
open(sys.argv[1],'w').write('\n'.join(L)+'\n')
print('vision fixture',px['image_grid_thw'].tolist(),features.shape)
